import org.eclipse.swt.SWT;
import org.eclipse.swt.layout.GridData;
import org.eclipse.swt.widgets.Composite;

public class Example {
    void setup(Composite composite) {
        // Should not match other GridData constructors or SWT.FILL directly
        GridData gd1 = new GridData();
        GridData gd2 = new GridData(SWT.LEAD, SWT.TOP, true, true);
        GridData gd3 = new GridData(100, 200);
        GridData gd4 = new GridData(SWT.FILL, SWT.FILL, true, true);
        composite.setLayoutData(gd1);
        composite.setLayoutData(gd2);
        composite.setLayoutData(gd3);
        composite.setLayoutData(gd4);
    }
